<?php
$keys=['workforce_pay_period_cadence','workforce_pay_period_anchor','workforce_pay_period_custom_days','workforce_period_deadline_time','workforce_period_auto_confirm','workforce_timezone','timezone'];$ph=implode(',',array_fill(0,count($keys),'?'));$st=$pdo->prepare("SELECT config_key,config_value FROM app_config WHERE organization_id=0 AND config_key IN ($ph)");$st->execute($keys);$payConfig=$st->fetchAll(PDO::FETCH_KEY_PAIR);$periodRows=$pdo->query('SELECT p.*,(SELECT COUNT(*) FROM worker_period_submissions s WHERE s.pay_period_id=p.id AND s.status IN ("submitted","accepted","adjusted")) submitted_count,(SELECT COUNT(*) FROM worker_statements ws WHERE ws.pay_period_id=p.id) statement_count FROM pay_periods p ORDER BY p.period_end DESC LIMIT 24')->fetchAll(PDO::FETCH_ASSOC);$statements=$pdo->query('SELECT ws.id,ws.status,ws.statement_type,ws.total_amount,ws.currency,wp.display_name,p.period_start,p.period_end FROM worker_statements ws JOIN worker_profiles wp ON wp.id=ws.worker_profile_id JOIN pay_periods p ON p.id=ws.pay_period_id ORDER BY p.period_end DESC,wp.display_name LIMIT 100')->fetchAll(PDO::FETCH_ASSOC);$h=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
?>
<form method="post" action="/?page=settings/workforce-catalog-handler" class="settings-primary-form"><input type="hidden" name="csrf" value="<?=$h(csrf_token())?>"><input type="hidden" name="action" value="save-pay-schedule"><input type="hidden" name="return_tab" value="pay-periods"><div class="settings-card"><h3>Organization pay and review schedule</h3><p>Review and payment use the same organization-wide period. Closed periods accept later corrections only as next-period adjustments.</p><div class="settings-form-grid"><label class="field"><span class="label">Cadence</span><select class="input" name="cadence"><?php foreach(['weekly'=>'Weekly','biweekly'=>'Biweekly','semimonthly'=>'Semimonthly','monthly'=>'Monthly','custom'=>'Custom days'] as $v=>$l):?><option value="<?=$v?>" <?=($payConfig['workforce_pay_period_cadence']??'biweekly')===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label class="field"><span class="label">Anchor date</span><input class="input" type="date" name="anchor" value="<?=$h($payConfig['workforce_pay_period_anchor']??'')?>"></label><label class="field"><span class="label">Custom days</span><input class="input" type="number" min="1" max="366" name="custom_days" value="<?=$h($payConfig['workforce_pay_period_custom_days']??'14')?>"></label><label class="field"><span class="label">Finalization deadline</span><input class="input" type="time" name="deadline_time" value="<?=$h($payConfig['workforce_period_deadline_time']??'20:00')?>"><small>Uses <?=$h($payConfig['workforce_timezone']??$payConfig['timezone']??'America/Chicago')?>. Workers are reminded 4, 2, and 1 hour before this time.</small></label><label class="check-row field--wide"><input type="checkbox" name="auto_confirm" value="1" <?=($payConfig['workforce_period_auto_confirm']??'1')==='1'?'checked':''?>> Automatically confirm completed entries at the deadline</label><p class="catalog-tax-note">At the deadline, completed entries are locked and earnings snapshots are generated. Running or incomplete timers move to Work Review. Later changes use the audited correction workflow.</p></div></div><div class="settings-save-bar"><p class="settings-save-status" data-settings-save-status>No unsaved changes</p><button class="btn btn-primary">Save schedule</button></div></form>
<div class="pa-table-wrap"><table class="pa-table"><thead><tr><th>Period</th><th>Cadence</th><th>Submissions</th><th>Status</th><th class="text-right">Action</th></tr></thead><tbody><?php foreach($periodRows as $row):?><tr><td><?=$h($row['period_start'])?> – <?=$h($row['period_end'])?></td><td><?=$h(ucfirst($row['cadence']))?></td><td><?=(int)$row['submitted_count']?></td><td><?=$h(ucfirst($row['status']))?><?php if($row['closed_at']):?><small><?=$h($row['closed_at'])?></small><?php endif;?></td><td class="text-right"><?php if($row['status']==='open'):?><form method="post" action="/?page=settings/workforce-catalog-handler" class="inline-form" onsubmit="return confirm('Close this period and issue statements? Missing submissions will stop the first attempt.')"><input type="hidden" name="csrf" value="<?=$h(csrf_token())?>"><input type="hidden" name="action" value="close-pay-period"><input type="hidden" name="return_tab" value="pay-periods"><input type="hidden" name="pay_period_id" value="<?=(int)$row['id']?>"><button class="btn btn-sm">Review &amp; close</button></form><form method="post" action="/?page=settings/workforce-catalog-handler" class="inline-form" onsubmit="return confirm('Close this period even if workers have not submitted it?')"><input type="hidden" name="csrf" value="<?=$h(csrf_token())?>"><input type="hidden" name="action" value="close-pay-period"><input type="hidden" name="return_tab" value="pay-periods"><input type="hidden" name="pay_period_id" value="<?=(int)$row['id']?>"><input type="hidden" name="force" value="1"><button class="btn btn-sm btn-danger">Close anyway</button></form><?php else:?><?=(int)$row['statement_count']?> statement<?=(int)$row['statement_count']===1?'':'s'?><?php endif;?></td></tr><?php endforeach;?><?php if(!$periodRows):?><tr><td colspan="5">Periods are created when work is first submitted.</td></tr><?php endif;?></tbody></table></div>
<?php if($statements):?><div class="settings-card"><h3>Issued statements</h3><div class="pa-table-wrap"><table class="pa-table"><thead><tr><th>Worker</th><th>Period</th><th>Type</th><th>Total</th><th>Status</th><th class="text-right">Action</th></tr></thead><tbody><?php foreach($statements as $statement):?><tr><td><?=$h($statement['display_name'])?></td><td><?=$h($statement['period_start'])?> – <?=$h($statement['period_end'])?></td><td><?=$statement['statement_type']==='contractor_settlement'?'Contractor settlement':'Employee pay'?></td><td><?=$h($statement['currency'])?> <?=number_format((float)$statement['total_amount'],2)?></td><td><?=$h(ucfirst($statement['status']))?></td><td class="text-right"><?php if($statement['status']==='issued'):?><form method="post" action="/?page=settings/workforce-catalog-handler" class="inline-form" onsubmit="return confirm('Mark this statement as settled?')"><input type="hidden" name="csrf" value="<?=$h(csrf_token())?>"><input type="hidden" name="action" value="settle-statement"><input type="hidden" name="return_tab" value="pay-periods"><input type="hidden" name="statement_id" value="<?=(int)$statement['id']?>"><button class="btn btn-sm btn-primary">Mark settled</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div><?php endif;?>
